let MainSearch = DeviceEvents | project DeviceId, ReportId, Timestamp | join (DeviceProcessEvents | project OtherReportId=ReportId, OtherTimestamp=Timestamp, DeviceId) on DeviceId;
let EnrichingResults = MainSearch | project DeviceId, ReportId=OtherReportId, Timestamp=OtherTimestamp;
union MainSearch, EnrichingResults
